import urllib.request, json
prefixes=['borzoi/','borzoi/f0/','borzoi/hg38/','borzoi-paper/']
for prefix in prefixes:
 url='https://storage.googleapis.com/storage/v1/b/seqnn-share/o?prefix='+prefix+'&maxResults=200'
 print('\\nPREFIX', prefix)
 try:
  data=json.load(urllib.request.urlopen(url, timeout=30))
  for item in data.get('items',[])[:50]: print(item['name'], item.get('size'))
  print('next', data.get('nextPageToken'))
 except Exception as e: print('ERR',e)
PY"

